static int binary_search(const int *values, size_t count, int target) {
    size_t low = 0;
    size_t high = count;
    while (low < high) {
        const size_t middle = low + (high - low) / 2;
        if (values[middle] < target) {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    if (low < count && values[low] == target) return (int)low;
    return -1;
}

